import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/SNS%E4%B8%AD%E6%AF%92%E3%82%84%E5%8B%95%E7%94%BB%E4%B8%AD%E6%AF%92%E3%81%AB%E3%81%A4%E3%81%84%E3%81%A6%E7%9F%A5%E3%81%A3%E3%81%A6%E3%81%8A%E3%81%8F%E3%81%B9%E3%81%8D%E4%BA%8B.html","title":"SNS中毒や動画中毒について知っておくべき事","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":7.47,"words":2242},"filePathRelative":"SNS中毒や動画中毒について知っておくべき事.md"}`),a={name:`SNS中毒や動画中毒について知っておくべき事.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="sns中毒や動画中毒について知っておくべき事" tabindex="-1"><a class="header-anchor" href="#sns中毒や動画中毒について知っておくべき事"><span>SNS中毒や動画中毒について知っておくべき事</span></a></h1><p>SNSとか動画を適切に接していくためには、必要な知識があると思う。</p><p>そうした知識は<a href="./【書籍】最強の集中力.html">【書籍】最強の集中力</a>と<a href="./ポモドーロテクニック.html">ポモドーロテクニック</a>の二つでだいたい十分と思うのだけど、 どちらも必要な事だけが書いてあるという訳でも無く、「それは違うんじゃないか？」と思うような事や、 このトピックとは関係ない話題も多い。</p><p>もう少し異論無く知っておくべきと思うような事をまとめられないか、という試みとしてこのページを書いてみる。</p><h2 id="認知的不協和" tabindex="-1"><a class="header-anchor" href="#認知的不協和"><span>認知的不協和</span></a></h2><p>この話題を考えるにあたり、認知的不協和について自覚するのは必要な事だ。</p><p>人は、本人が考えている事と実際の状態に矛盾がある時に、強いストレスを感じる傾向がある。これを認知的不協和という。 そしてそういう状態になると、考えの方を変更してストレスを解消しようとする強い圧力が生じる。</p><p>この認知的不協和のせいで、本来は「本人が良いと思う程度にするのが良い」というものであるはずが、 その良いと思う程度を歪められてしまうという問題がある。</p><p>喫煙者がタバコが良くないという話に強い反発を覚えたり、 動画をめっちゃたくさん見てしまっている人がそういうのが良くないという話に強い反発を抱く反応。</p><p>自分の何かに問題があるか、という事を考える時には、認知的不協和の力が働いているかを考えてみるのは有意義。</p><p>また、何か問題のある状態になってからそれを自覚するよりも、問題のある状態になる前に問題かどうかを考える方がニュートラルに考えやすい。</p><h2 id="注意散漫" tabindex="-1"><a class="header-anchor" href="#注意散漫"><span>注意散漫</span></a></h2><p>ここでは、何かをやろうとした時に、それに集中出来ずにそれ以外の事をやってしまう状態を注意散漫と定義する。</p><p>気晴らしや息抜き、暇つぶしをしようとしてそれをしている状態と、 本来違う事をやろうとしていたはずなのにそれをしている状態は区別したい。 ただし後者には認知的不協和が働くので、後者ではないと自分で思う時にもある程度は懐疑的になっておく必要がある。</p><h3 id="注意散漫を狙ったサービスがあると自覚する" tabindex="-1"><a class="header-anchor" href="#注意散漫を狙ったサービスがあると自覚する"><span>注意散漫を狙ったサービスがあると自覚する</span></a></h3><p>多くのサービスは、注意をひこうと通知や他に見るものの推薦など、多くの手段を使う。 何かの動画などを見た時に、その動画の後に推薦される動画をつい見てしまったり、 横に表示される動画を見てしまう、というのはあるだろう。</p><p>暇つぶしをしたい時にそれらを使うのは適切であるが、何かの目的を持ってそれを見ている時にそういうのに引っかかってしまうのは注意散漫となる。</p><p>また、違う事をやっている時に通知が来て気が散ってしまうのは注意散漫である。 何かを受け取りたくて待っている時に来る通知とは区別したい。</p><p>幾つかのサービスは、注意を絶えず自分の側に惹きつけようとする。 それとは違う事をやろうとしている時には、それはいつも注意散漫を狙っているサービスとなる。</p><p>必要な時に注意を向けられるようにしつつ、他の事に注意を向けたい時に気を散らさない為には、 意図的にそうしたものをコントロールしていく必要がある。 コントロールの第一歩は、コントロールする必要があるものだ、と自覚する事にある。</p><p>注意散漫を引き起こしやすいサービスやアプリがいくつかあり、 そうしたものに接する時には「これは注意散漫を引き起こしやすいサービスなので気をつけよう」と思う必要がある。</p><h3 id="注意散漫かどうかは時と場合による" tabindex="-1"><a class="header-anchor" href="#注意散漫かどうかは時と場合による"><span>注意散漫かどうかは時と場合による</span></a></h3><p>同じ機能でも、状況によって有益になったり有害になったりする。 関連動画をいろいろと探している時には便利な機能や、必要な反応を待っている時に通知をくれる便利な機能が、 他の事をやろうとしている時には注意散漫を引き起こす事がある。</p><p>前者を便利に使いつつ後者を抑制したい。</p><h3 id="注意散漫に気づく方法" tabindex="-1"><a class="header-anchor" href="#注意散漫に気づく方法"><span>注意散漫に気づく方法</span></a></h3><p>現在の自分にとってそのサービスが有益なのか注意散漫を引き起こしているのか、というのは、究極的には自分にしか分からない。 だからこうした判断は自分でする必要がある。</p><p>自分で判断するためには、注意散漫が起きた時に、それを自覚するのが良い。 「この本を今から30分読もう」と思っている時にSNSを触ったらそれは注意散漫だ。</p><p>注意散漫に気づく事が出来れば、それを何度も積み重ねていく事で、自分はどういうサービスのどの機能が注意散漫を引き起こしやすいのか、 という事も理解出来るようになる。</p><h3 id="注意散漫を引き起こしがちな機能" tabindex="-1"><a class="header-anchor" href="#注意散漫を引き起こしがちな機能"><span>注意散漫を引き起こしがちな機能</span></a></h3><p>いくつかの機能は注意散漫を引き起こしがちなので、知っておくと自覚しやすい。</p><ul><li>通知</li><li>推薦</li><li>メッセージなどへの反応</li></ul><p>メッセージなどへの反応は後で扱う。</p><p>注意を引きつけようとするサービスの基本は、まず何かを見せて、それを見た人にさらに続きを見せる、という事を狙う。</p><p>最初に何かを見せるのに一番使われているのが通知だ。</p><p>何かを見た人に続きを見せる為に使われるのが推薦だ。この動画を見た人はこの動画も見ています、とか、 このミッションを終えたら次はこれをやりましょう、とか、そうした、 何かが終わった時（や表示した時）などに次にやる事への誘導をするのが推薦だ。</p><p>この二つは注意散漫を引き起こしやすい機能だが、便利な機能でもあるので、 注意しつつ使っていくのが良いんじゃないか。</p><h2 id="集中の基本的な性質" tabindex="-1"><a class="header-anchor" href="#集中の基本的な性質"><span>集中の基本的な性質</span></a></h2><p>集中という性質を理解しておくのも、注意散漫と戦うには必要な事となる。 なお、<a href="./ポモドーロテクニック.html">ポモドーロテクニック</a>を使っていればそれだけで必要な事は全て学べるので、こういう説明を読むのがかったるい人はポモドーロを試してみる事をオススメする。</p><h3 id="最初の5分間くらいに難しさがある" tabindex="-1"><a class="header-anchor" href="#最初の5分間くらいに難しさがある"><span>最初の5分間くらいに難しさがある</span></a></h3><p>集中は入るまでに難しさがある。一度入ってしまえばしばらく続けるのはそんなに大変でも無い。 本を読むという事を考えると、本を読み始める所に難しさがあり、 また読み始めて最初のちょっとで違う事をしてしまうという難しさがある。 ここを乗り越えると40分くらい読むのはそんなに難しくない。</p><p>入る所に難しさがあり、そして1時間ないくらいで切れる。</p><p>集中に入るためには、最初の数分間を乗り越える必要があり、ここが一番難しいので、心の準備をして立ち向かうのが良い。 注意散漫が一番入りやすいのもここなので、最初の5分に注意散漫が入る時にはまずはその環境を変更して注意散漫が入らないように心がけたい。 これはあとで述べる外部誘引を無くすだけでは不十分で、 内部誘引にも対抗する必要がある。</p><p>何にせよ、最初の5分が難しく、そこを乗り越えれば後は楽、という事は知識として知っておいた方が良い。</p><h3 id="集中は続けるよりも、入る方が難しい" tabindex="-1"><a class="header-anchor" href="#集中は続けるよりも、入る方が難しい"><span>集中は続けるよりも、入る方が難しい</span></a></h3><p>一度集中状態になったら、それを1時間弱くらい続けるのは難しくない。 一方で一度集中状態が解除されると、また入るのに最初の困難な5分を乗り越える必要がある。</p><p>だから一度集中したら、しばらくは集中を続ける方が楽で良い。</p><p>一度途切れるとまた入るのが大変なので、なるべく途切れさせないようにしよう。</p><p>何かのタスクの割り込みは、その割り込みの時間だけでは無く、また集中状態に入るまでの時間も無駄にするので、 割り込みが30秒でも実際は5分以上の無駄になっている事がある。 集注を途切れさせる割り込みは過小評価しがちなので、 気づいたら注意しよう。</p><h3 id="集中の観点から見た注意散漫" tabindex="-1"><a class="header-anchor" href="#集中の観点から見た注意散漫"><span>集中の観点から見た注意散漫</span></a></h3><p>集中、という事を考えるに、以下の二つのポイントに注意散漫が関わってくる。</p><ul><li>最初の5分に気が散る <ul><li>最初の5分は困難なので注意散漫があるとさらに難しくなる</li></ul></li><li>一度集中状態になった後にそれを途切れさせる <ul><li>ちょっとの割り込みも要注意</li></ul></li></ul><p>最初の5分は完全に注意散漫が無い状態を作ってやらないとなかなか集注状態にはなれない。 ここは意図的にそういう環境を作っていく必要があるだろう。 <a href="./ポモドーロテクニック.html">ポモドーロテクニック</a>のポモドーロアプリなどはそうした環境を作る良い方法だが、別に他の方法でも良い。</p><p>一度集注状態になったあとにそれを維持するのは、最初の5分よりは容易だ。 数秒の割り込みくらいなら、集注を維持させる事は出来る事が多い（たまに解かれちゃう事もあるが）。 だから最初の5分のように完全に割り込みを排除する必要は無い。 ただ解除するのはやはりコストが掛かる事なので、 あまり割り込みは無い方が良い。</p><h3 id="集中から見る通知と推薦" tabindex="-1"><a class="header-anchor" href="#集中から見る通知と推薦"><span>集中から見る通知と推薦</span></a></h3><p>注意散漫の引き起こしやすい機能である通知と推薦について、集中の観点から考えてみる。</p><p>集中にとって一番気をつけるべきは通知だ。 最初の5分に通知が来るとだいたい集中に入るのは失敗するので最初の5分には通知が来ないようにすべきだ。 集中に入っている状態で通知が来るのは、最初の5分ほど致命的では無く維持を続ける事が出来る場合もあるが、 切れる事もあるのでやはり無いにこしたことは無い。 集中に入る時には通知の管理は重要になる。</p><p>通知に比べると推薦はそこまでの被害は無い。 基本的には集中状態で何か調べ物をする時に、その調べ物以外に気が散る、というパターンで入ってくるのが唯一の被害だ。 対策は二つ。何かを調べる時に他の事があまり目に入らないように環境を整備する、という事。 そして目に入った時にも「今はこういうのは見ない」と意識的に避ける。</p><h2 id="注意散漫と内的誘引と外的誘引" tabindex="-1"><a class="header-anchor" href="#注意散漫と内的誘引と外的誘引"><span>注意散漫と内的誘引と外的誘引</span></a></h2><p>注意散漫のメカニズムを知っておくのも対抗するために有意義である。 大まかには内的誘引と外的誘引に分けられて、内的誘引の方が強力だ。</p><h3 id="内的誘引" tabindex="-1"><a class="header-anchor" href="#内的誘引"><span>内的誘引</span></a></h3><p>何かに集中する時に気が散る一番の要因は内的誘引となる。 内的誘引は、心の不快感から逃れようとする反応。</p><p>心の不快感に遭遇すると、反射的にそれから逃れようとして、別の事をしようとする。</p><p>例えば読んでいる文書に不快だったり好きになれないような内容があったり、 または難しくて良く分からない事があったりすると、無意識に違う事を始めようとする。</p><p>不快というのは大げさな事も多く、多くの場合はほんの小さな事だったりする。 自覚してしまえば「こんな些細な事どうって事無いな」と乗り越えるのは簡単な事がほとんどなので、 他に逃れようとする瞬間にそれを自覚するのが一番の対策となる。</p><p>他の事に逃れようとする時に、それが内的誘引なのかどうかを自問して、 内的誘引だった時には何がその原因となっているのかを見つめるのが良い。 繰り返していると慣れてくるので、自然に出来るようになる。</p><h3 id="外的誘引" tabindex="-1"><a class="header-anchor" href="#外的誘引"><span>外的誘引</span></a></h3><p>外的誘引は通知とかの他の刺激で注意がそれる事だ。 こちらは注意散漫という時に良くイメージする事だと思うので別段追加する事も無い。</p><p>単体ではそこまで強力でもなく、内的誘引がある時にそれを補強するような形で働く事が多い。 逆に外的誘引が多い状態だと、些細な内的誘引にも引っ掛りやすくなる。</p><p>外的誘引は環境を整備して減らしやすいので、対処も比較的容易で効果も出やすい。</p><h3 id="これらの誘引による衝動は長続きしない事が多い" tabindex="-1"><a class="header-anchor" href="#これらの誘引による衝動は長続きしない事が多い"><span>これらの誘引による衝動は長続きしない事が多い</span></a></h3><p>内的誘引も外的誘引も、違う事をはじめてしまう強い衝動を生むが、 この衝動は長続きしない事がほとんどだ。</p><p>だから一瞬違う事をやりたくなった時にも、｢ぐっ｣と少しだけ踏み止まれれば、 すっと消えていく事が多い。</p><p>衝動を一瞬耐えるだけで良い、という事を知っておくと、耐えるのもずっと楽になるだろう。 対策としても、必要なのは長期間持続する強い意思ではなく、 一瞬の衝動を自覚してやりすごす、という、知識の問題である事も多い。 この辺がこの文書を書こうと思った理由でもある。</p><h2 id="他人とのメッセージのやりとり" tabindex="-1"><a class="header-anchor" href="#他人とのメッセージのやりとり"><span>他人とのメッセージのやりとり</span></a></h2><p>メールやチャットなども注意散漫の原因になりがちだ。 だが他人との連絡は、単にどうでもいい動画やつぶやきを見てしまうのとは違い、 必要なものがある確率が相対的に高いので、 避けるのではなくコントロールをする、という要素がより高い。</p><p>以下ではメールやチャットなどのメッセージのやりとりについて述べる。</p><h3 id="確認や返答を遅らせる事について考える" tabindex="-1"><a class="header-anchor" href="#確認や返答を遅らせる事について考える"><span>確認や返答を遅らせる事について考える</span></a></h3><p>メッセージによる注意散漫に対する、一番簡単で有効な対策は、単に確認や返答を遅らせる、というものだ。 集中状態ではそうした事は行わず、集中を終えたあとにまとめてやれば良い。</p><p>集中するという習慣が無いと、メッセージをすぐに確認して反応したくなると思う。 そこで最初は、普段やりとりしているメッセージのうち、どのくらいが後回しにしても問題無いかを考えてみる事から始めるのが良い。</p><p><a href="./ポモドーロテクニック.html">ポモドーロテクニック</a>を使っているのであれば、集中は25分間だ。 この間のメッセージの確認を後回しにする時の、平均の後回しにする時間は12.5分となる。 12.5分あとまわしにして問題があるメッセージがどれだけあるか？を確認してみる。</p><p>多くの場合、12.5分あとまわしにする事は問題無いはずだ。 それなりに急いで返答した方が良いメッセージでも、30分程度遅くなる事にはほとんど問題が無い、 というものも多い。</p><p>また、12.5分のあとまわしが問題になるようなメッセージがある人でも、 そういうメッセージは、あらかじめ届くタイミングがある程度予期できるものがほとんどだと思う。</p><p>そこで、集中を開始するのは、そうしたメッセージが来ないとわかっているタイミングで行うようにする。 そして集中しようとしている時はメッセージの通知は切り、見えたとしても確認を後回しにするようにすると、 メッセージの注意散漫はほぼ防げると思う。</p><h3 id="単に遅らせるその他の効用" tabindex="-1"><a class="header-anchor" href="#単に遅らせるその他の効用"><span>単に遅らせるその他の効用</span></a></h3><p>ぱっと目についた事に返信するのを少し遅らせるのは、注意散漫を防ぐ以外にも効用がある。 あまり有意義でないやりとりをしているな、と思ったら、少し遅らせてみるのは有効な事が多い。</p><p>SNSなどでは衝動的は反応を狙う事が反応をもらおうとする発言も多いが、 そうした衝動は一瞬しか続かないので、単に少し遅らせれば、反応したいという気持ち自体が消える。</p><p>こうした衝動による反応は、有益な事もまれにあるが、まったくろくでも無い事の方が多数だろう。 ろくでもない衝動による反応をしている量が多いな、と思ったら、少し遅らせる事で、だいたい解決する。</p><p>より個人的な相手とのメッセージのやりとりでも、 感情的になっているのが良くない方向に働いたり、 特に意義の無いやりとりが続いたりする事もある。 単に少し反応を遅らせるだけで、そうした問題は簡単に軽減出来るので、 メッセージの確認を遅らせたり返答を遅らせるのは、有効なツールの一つだ。</p><h2 id="注意散漫に対抗するツールたち" tabindex="-1"><a class="header-anchor" href="#注意散漫に対抗するツールたち"><span>注意散漫に対抗するツールたち</span></a></h2><p>この問題に対処するのに有効なツールを幾つか述べる。 これらは全て使うべき、というものではなく、必要に応じて使いたいものを使えば良い。</p><p>むしろ必要な時に使えるように、知識として知っておくのが大切、というものになる。</p><h3 id="ポモドーロテクニック" tabindex="-1"><a class="header-anchor" href="#ポモドーロテクニック"><span>ポモドーロテクニック</span></a></h3><p><a href="./ポモドーロテクニック.html">ポモドーロテクニック</a>は注意散漫に対抗するのにもっとも簡単に使えて効果が高いツールだと思う。 一方、強力すぎて｢そこまで集中しなくてもいいいのになぁ〜｣と思う事もあるので、 どちらかというとそこまで困ってないなら使わなくてもいい、という類のツール。</p><h3 id="通知の設定" tabindex="-1"><a class="header-anchor" href="#通知の設定"><span>通知の設定</span></a></h3><p>スマホの通知は、アプリ毎に設定出来る。 この設定はちゃんとした方がいい。</p><p>集中しようとした時に通知が来たら、その通知をオフに出来る時はオフにする。 通知には自分に必要な通知と、自分には不要なものをサービス側が押しつけようとする通知があり、 昨今は後者の方が多い。</p><p>けれど多くのアプリでは、必要なものだけ残すような設定があるので、 不要な通知は切るようにしたい。</p><p>必要な通知だけを残せないサービスが多い場合はポモドーロ時に通知を抑制するようなアプリと併用する事になるが、 単に不要な通知をいちいち切っていくだけで十分な事も多い。</p><h3 id="書き出して後回しにする" tabindex="-1"><a class="header-anchor" href="#書き出して後回しにする"><span>書き出して後回しにする</span></a></h3><p>メッセージの所でも述べた通り、あとまわしにするのは有効なツールだ。</p><p>集中しようとしている時に、何か他の事をしたい、と思った時は、書き出して後回しにするのは衝動を抑えるのに有効な事が多い。 書き出す事で、ちゃんとあとでやる、という事を感情が納得しやすいし、 そのおかげで一瞬の衝動をやりすごすのが簡単になる。</p><p>単に気になる事を書きだしておくだけ、も有効なツールであるが、後回しと併用するとさらに強力だ。</p><h3 id="調べる事は後回しにする" tabindex="-1"><a class="header-anchor" href="#調べる事は後回しにする"><span>調べる事は後回しにする</span></a></h3><p>集中している時にスマホなどに邪魔されるパターンとして、調べものから始まるものがある。 調べようとすると、世の中のサービスはついでにいろいろ見せてこようとしがちだ。</p><p>調べる必要があるものでも、後回しに出来るものもある。 調べる事は集中を切らされるリスクがあるので、やるなら集中の最後の方にやる方が良い。 集中の最後にやって集中を切らされても、あまり被害は無いから。</p><p>調べたい項目によってはすぐに調べた方がいいものもある。 そういうのは後回しには出来ないだろう。その場合は仕方ないので、集中が切れない事を祈りつつ調べるしかない。</p><p>けれど後回しにしても良いものも結構ある。 後回しに出来るものを後回しにすれば、それだけ調べ物で集中が切れる確率を減らす事が出来る。 間にこまごまと調べるよりも、なるべく集中の最後にまとめて調べたい。</p><p>あとで調べてもいいものは後に調べるようにしよう。</p><p>なお、集中の最後よりももっと後でも構わないものもある。 そういうものは前述の書き出して後回し、で集中の外に出してしまうとより良い。</p><h3 id="良し悪しを少し長期間で考える" tabindex="-1"><a class="header-anchor" href="#良し悪しを少し長期間で考える"><span>良し悪しを少し長期間で考える</span></a></h3><p>本を読もうと思っていた所で、ついYouTubeを見てしまったとする。 これが良い事か？と考えるのは難しい。</p><p>YouTubeに限らず、今やっている事が良い事か悪い事か、と考えるのは、 一般に認知的不協和が強く働くので難しい事だ。 悪い事をやっている時に悪いかどうかを考えるのは、ストレスが高いしあまりうまく行かない。 言い訳する自分と戦っても不毛だ。</p><p>それよりは、昨日一日はどうだったか？と考える方が、 より中立的に考えやすい。 昨日一日がいい感じだと思うなら、個々の行動の是非はおいといておおすじでは問題は無いのだろう。 昨日一日が全体としていい感じでないのなら、どれを直すべきかはおいといて、何かは直すべきだろう。</p><p>昨日一日よりも、先週一週間の方がより考えやすい。 先週一週間よりも先月一ヶ月の方がより考えやすい。 一年とかになるとまた違う話になるので、この話題なら一ヶ月くらいを上限に考えるのがいいんじゃないか。</p><p>どのくらいだと気晴らしや娯楽や有益な何かとして使えていて、 どこまで行くと有害だったりやり過ぎなのか、という事を考える時には、 今やっている事を考えるのではなく、少し長い期間で考える方が良い。</p><p>そこで考えて決めた分量に応じて、今日のつきあい方を決めていく。</p>`,116)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};